function m1QuestionVisualMeta(lessonKey: string): QuestionVisualMeta | undefined {
  switch (lessonKey) {
    case "M1L1":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L1/diagrams/m1_l1_distance_time_graph.svg`,
        visual_title: "Distance-time story board",
        visual_caption: "The distance-time graph keeps the axes, pause section, and steeper final segment visible in one journey story.",
        visual_callouts: [
          "Graph height shows the recorded distance by that time.",
          "A flat section means the traveler is paused.",
          "A steeper segment means a greater speed.",
        ],
      };
    case "M1L2":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L2/diagrams/m1_l2_speed_time_graph.svg`,
        visual_title: "Speed-time graph",
        visual_caption: "This graph keeps graph height and graph slope separate so speed and acceleration are read from the correct feature.",
        visual_callouts: [
          "Graph height at a chosen time gives the speed at that time.",
          "A rising line means positive acceleration.",
          "Flat above zero still means motion at constant speed.",
        ],
      };
    case "M1L3":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L3/diagrams/m1_l3_signed_acceleration_graph.svg`,
        visual_title: "Signed velocity and acceleration graph",
        visual_caption: "This velocity-time graph keeps velocity sign on the axis and acceleration sign in the slope.",
        visual_callouts: [
          "Velocity sign is read from whether the graph is above or below the axis.",
          "Acceleration sign is read from the slope direction.",
          "A positive slope can act while the velocity is still negative.",
        ],
      };
    case "M1L4":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L4/diagrams/m1_l4_constant_acceleration_graph.svg`,
        visual_title: "Constant-acceleration forecast graph",
        visual_caption: "This velocity-time forecast keeps one steady slope visible so the constant-acceleration condition is easy to see.",
        visual_callouts: [
          "A straight velocity-time line means one steady acceleration throughout.",
          "Graph and equation reasoning agree only while that condition holds.",
          "The knowns and unknown still decide which equation is the best tool.",
        ],
      };
    case "M1L5":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L5/diagrams/m1_l5_speed_gradient_graph.svg`,
        visual_title: "Gradient meaning comparator",
        visual_caption: "The M1 comparison uses one distance-time graph and one speed-time graph so slope meaning stays tied to the axes.",
        visual_callouts: [
          "The paired graphs must be named before the slope is named.",
          "On distance-time, slope gives speed.",
          "On speed-time, slope gives acceleration.",
        ],
      };
    case "M1L6":
      return {
        image_url: `${M1_ASSET_BASE}/M1_L6/diagrams/m1_l6_area_distance_graph.svg`,
        visual_title: "Area-to-distance builder",
        visual_caption: "This speed-time graph keeps the shaded region under the graph so the total area can be read as total distance.",
        visual_callouts: [
          "On a speed-time graph, area accumulates distance.",
          "The whole shaded region matters, not just the outline shape.",
          "Different shapes can still match if the total area is the same.",
        ],
      };
    default:
      return undefined;
  }
}

function questionVisualMeta(item: UnknownRecord): QuestionVisualMeta | undefined {
  const id = text(item.id).toUpperCase();
  const normalizedId = id.replace(/-/g, "");
  const remappedVisual = remappedLateCoreQuestionVisualMeta(normalizedId);
  if (remappedVisual) return remappedVisual;
  const m13Visual = m13QuestionVisualMeta(normalizedId);
  if (m13Visual) return m13Visual;
  const m14Visual = m14QuestionVisualMeta(normalizedId);
  if (m14Visual) return m14Visual;
  const a5Visual = a5QuestionVisualMeta(normalizedId);
  if (a5Visual) return a5Visual;
  const a4Visual = a4QuestionVisualMeta(normalizedId);
  if (a4Visual) return a4Visual;
  const a3Visual = a3QuestionVisualMeta(normalizedId);
  if (a3Visual) return a3Visual;
  const a2Visual = a2QuestionVisualMeta(normalizedId);
  if (a2Visual) return a2Visual;
  const a1Visual = a1QuestionVisualMeta(normalizedId);
  if (a1Visual) return a1Visual;
  const m2Visual = m2QuestionVisualMeta(normalizedId);
  if (m2Visual) return m2Visual;
  const m3Visual = m3QuestionVisualMeta(normalizedId);
  if (m3Visual) return m3Visual;
  const m4Visual = m4QuestionVisualMeta(normalizedId);
  if (m4Visual) return m4Visual;
  const m5Visual = m5QuestionVisualMeta(normalizedId);
  if (m5Visual) return m5Visual;
  const m6Visual = m6QuestionVisualMeta(normalizedId);
  if (m6Visual) return m6Visual;
  const m7Visual = m7QuestionVisualMeta(normalizedId);
  if (m7Visual) return m7Visual;
  const m8Visual = m8QuestionVisualMeta(normalizedId);
  if (m8Visual) return m8Visual;
  const m9Visual = m9QuestionVisualMeta(normalizedId);
  if (m9Visual) return m9Visual;
  const m10Visual = m10QuestionVisualMeta(normalizedId);
  if (m10Visual) return m10Visual;
  const m11Visual = m11QuestionVisualMeta(normalizedId);
  if (m11Visual) return m11Visual;
  const m12Visual = m12QuestionVisualMeta(normalizedId);
  if (m12Visual) return m12Visual;
  const m1Match = normalizedId.match(/^(M1L[1-6])_[A-Z]+\d+$/);
  if (m1Match) return m1QuestionVisualMeta(m1Match[1]);
  const foundationMatch = normalizedId.match(/^(F[1-4]L[1-6])_[A-Z]+\d+$/);
  return foundationMatch ? FOUNDATION_VISUAL_META[foundationMatch[1]] : undefined;
}

