function coreModuleNumber(code: string): number | null {
  const match = /^M(\d+)_L\d+$/i.exec(code);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
}

function isM1ToM14Lesson(code: string): boolean {
  const moduleNumber = coreModuleNumber(code);
  return moduleNumber !== null && moduleNumber >= 1 && moduleNumber <= 14;
}

function advancedModuleNumber(code: string): number | null {
  const match = /^A(\d+)_L\d+$/i.exec(code);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
}

function isA1ToA11Lesson(code: string): boolean {
  const moduleNumber = advancedModuleNumber(code);
  return moduleNumber !== null && moduleNumber >= 1 && moduleNumber <= 11;
}

function singleLineText(value: string): string {
  return text(value).replace(/\s+/g, " ").trim();
}

function ensureSentence(value: string): string {
  const trimmed = singleLineText(value);
  if (!trimmed) return "";
  return /[.!?]$/.test(trimmed) ? trimmed : `${trimmed}.`;
}

function lowerFirst(value: string): string {
  if (!value) return "";
  return value.charAt(0).toLowerCase() + value.slice(1);
}

function firstAnalogySentence(lesson: UnknownRecord): string {
  const analogyText = text(asRecord(phases(lesson).analogical_grounding).analogy_text).trim();
  if (!analogyText) return "";
  return normalizeRenderedPhysicsText(analogyText.match(/.*?[.!?](?:\s|$)/)?.[0]?.trim() || analogyText);
}

function isModuleEntryLesson(code: string): boolean {
  return /^(F[1-5]|M(?:[1-9]|1[0-4])|A(?:[1-9]|1[0-1]))_L1$/i.test(code);
}

function fullAnalogyMappingLines(lesson: UnknownRecord): string[] {
  const analogyMap = asRecord(asRecord(lesson.authoring_contract).analogy_map);
  return dedupeText(
    asList(analogyMap.mapping)
      .map((entry) => normalizeRenderedPhysicsText(ensureSentence(text(entry))))
      .filter(Boolean)
  );
}

function entryLessonAnalogyTable(lesson: UnknownRecord): UnknownRecord | null {
  const code = lessonCode(lesson);
  if (!isModuleEntryLesson(code)) return null;

  const analogyMap = asRecord(asRecord(lesson.authoring_contract).analogy_map);
  const definitionParts = dedupeText([
    ensureSentence(text(analogyMap.comparison)),
    ensureSentence(firstAnalogySentence(lesson)),
  ]).filter(Boolean);
  const mappingLines = fullAnalogyMappingLines(lesson);

  if (definitionParts.length === 0 && mappingLines.length === 0) return null;

  return {
    title: "Lesson analogy",
    caption: [
      ...definitionParts,
      "Before you use the first visual, name the analogy and match each picture object to the physics idea it represents.",
    ].join(" "),
    columns: ["Analogy-to-physics map"],
    rows: (mappingLines.length > 0 ? mappingLines : definitionParts).map((line) => [line]),
  };
}

function withEntryLessonAnalogyTable(lesson: UnknownRecord, tables: UnknownRecord[]): UnknownRecord[] {
  const entryTable = entryLessonAnalogyTable(lesson);
  if (!entryTable) return tables;
  return [entryTable, ...tables];
}

function analogyTextForCoreModule(code: string, value: string): string {
  const moduleNumber = coreModuleNumber(code);
  const replacements = moduleNumber ? CORE_MODULE_ANALOGY_REPLACEMENTS[moduleNumber] || [] : [];
  let rewritten = singleLineText(value);
  replacements.forEach(([pattern, replacement]) => {
    rewritten = rewritten.replace(pattern, replacement);
  });
  return rewritten;
}

function normalizedFormulaConditionLead(wrapper: string, lead: string): string {
  const normalizedWrapper = wrapper.toLowerCase();
  const normalizedLead = lead.toLowerCase();
  if (normalizedWrapper === "only when") {
    return normalizedLead === "as" ? "only as " : `only when ${normalizedLead} `;
  }
  return normalizedLead === "when" ? "when " : `${normalizedLead} `;
}

function trimmedFormulaCondition(value: string): string {
  return singleLineText(value)
    .replace(/[.!?]+$/g, "")
    .replace(
      /\b(only\s+when|when)\s+use\s+(?:(?:this|the)\s+(?:relation|formula|equation)\s+|it\s+)?(when|for|to|as|in|during|with|after)\s+/gi,
      (_match, wrapper: string, lead: string) => normalizedFormulaConditionLead(wrapper, lead)
    )
    .replace(
      /^use (?:(?:this|the)\s+(?:relation|formula|equation)\s+|it\s+)?(when|for|to|as|in|during|with|after)\s+/i,
      (_match, lead: string) => `${lead.toLowerCase()} `
    )
    .trim();
}

function formulaConditionInstruction(value: string, subject = "Use it"): string {
  const condition = trimmedFormulaCondition(value);
  if (!condition) return "";

  const explicitLead = /^(when|for|to|as|in|during|with|after)\s+(.+)$/i.exec(condition);
  if (explicitLead) {
    const [, lead, rest] = explicitLead;
    return ensureSentence(`${subject} ${lead.toLowerCase()} ${lowerFirst(rest.trim())}`);
  }

  return ensureSentence(`${subject} when ${lowerFirst(condition)}`);
}

function formulaUnitsText(formula: UnknownRecord): string {
  const units = asList(formula.units)
    .map((unit) => canonicalizeRenderedUnitTokens(text(unit)))
    .filter(Boolean);
  return units.length ? canonicalizeRenderedUnitTokens(units.join(", ")) : "No unit list supplied.";
}

function standardFormulaText(formula: UnknownRecord): string {
  return (
    text(formula.equation) ||
    text(formula.formula) ||
    text(formula.relation) ||
    text(formula.expression)
  );
}

function lessonFormulaRecords(lesson: UnknownRecord): UnknownRecord[] {
  const seen = new Set<string>();
  const formulaRecords: UnknownRecord[] = [];

  [...asList(asRecord(lesson.authoring_contract).formulas), ...asList(lesson.formulas)]
    .map(asRecord)
    .forEach((formula) => {
      const standardFormula = standardFormulaText(formula);
      const key = singleLineText(standardFormula).toLowerCase();
      if (!key || seen.has(key)) return;
      seen.add(key);
      formulaRecords.push(formula);
    });

  return formulaRecords;
}

function analogyMappingLines(lesson: UnknownRecord): string[] {
  return fullAnalogyMappingLines(lesson).slice(0, 2);
}

function formulaSectionRows(
  formulaCards: UnknownRecord[],
  fallbackConstantNote = "",
): { rows: UnknownRecord[]; constantNote: string; sharedAnalogy: string } {
  const uniqueConstants = dedupeText([
    ...formulaCards.map((card) => text(card.constants)).filter(Boolean),
    ...(fallbackConstantNote ? [fallbackConstantNote] : []),
  ]);
  const useSectionConstantNote = uniqueConstants.length === 1;
  const analogyEntries = formulaCards
    .map((card) => ({
      raw: text(card.analogy_equivalent),
      normalized: normalizeFormulaBridgeText(text(card.analogy_equivalent)),
      sentences: formulaBridgeSentences(text(card.analogy_equivalent)),
    }))
    .filter((entry) => entry.normalized);
  const uniqueAnalogies = [...new Set(analogyEntries.map((entry) => entry.normalized))];
  const sharedAnalogySentences: string[] = [];
  if (analogyEntries.length > 1) {
    const maxPrefixLength = Math.min(...analogyEntries.map((entry) => entry.sentences.length));
    for (let index = 0; index < maxPrefixLength; index += 1) {
      const candidateSentence = analogyEntries[0]?.sentences[index] ?? "";
      if (!candidateSentence) break;
      const allMatch = analogyEntries.every((entry) => entry.sentences[index] === candidateSentence);
      if (!allMatch) break;
      sharedAnalogySentences.push(candidateSentence);
    }
  }
  const useSharedAnalogy =
    (uniqueAnalogies.length === 1 && analogyEntries.length > 1) ||
    (sharedAnalogySentences.length > 0 && analogyEntries.length > 1);
  const sharedAnalogy =
    uniqueAnalogies.length === 1 && analogyEntries.length > 1
      ? analogyEntries[0]?.raw.trim() ?? ""
      : sharedAnalogySentences.join(" ").trim();

  return {
    rows: formulaCards.map((card) => ({
      ...card,
      constants: useSectionConstantNote ? "" : text(card.constants),
      analogy_equivalent: useSharedAnalogy
        ? stripFormulaBridgePrefix(text(card.analogy_equivalent), sharedAnalogySentences)
        : text(card.analogy_equivalent),
    })),
    constantNote: useSectionConstantNote ? uniqueConstants[0] : "",
    sharedAnalogy,
  };
}

function formulaConstantsText(code: string, formula: UnknownRecord): string[] {
  const combined = `${text(formula.equation)} ${text(formula.meaning)} ${text(formula.conditions)}`;
  const notes: string[] = [];

  if (/\bg\b/.test(text(formula.equation)) || /gravitational field strength/i.test(combined)) {
    notes.push("Near Earth, use g ≈ 10 N/kg (or 9.8 N/kg when specified).");
  }
  if (/specific heat/i.test(combined)) {
    notes.push("c is the material-specific heat capacity.");
  }
  if (/latent heat|phase change/i.test(combined)) {
    notes.push("L is the material-specific latent heat for that state change.");
  }
  if (/360\s*degrees|360°|15 degrees per hour/i.test(combined) || /24\s*h\b/i.test(combined)) {
    notes.push("One full Earth rotation is 360° in 24 h.");
  }
  if (/23\.4|23\.5/.test(combined) || /axial tilt/i.test(combined)) {
    notes.push("Earth's axial tilt is about 23.4°.");
  }
  if (/20\s*hz/i.test(combined) || /20[, ]?000\s*hz/i.test(combined) || /audible range/i.test(combined)) {
    notes.push("Typical human hearing spans about 20 Hz to 20 kHz.");
  }
  if (/\bplanck\b/i.test(combined) || (/\bh\b/.test(text(formula.equation)) && /photon|quantum|de broglie|frequency|wavelength/i.test(combined))) {
    notes.push("Use Planck's constant h = 6.63 × 10^-34 J s.");
  }
  if (/speed of light|relativ|mass[- ]energy|cosmology|redshift|photon/i.test(combined) && /\bc\b/.test(text(formula.equation))) {
    notes.push("Use c = 3.0 × 10^8 m/s in vacuum.");
  }
  if (/molar gas constant|ideal gas/i.test(combined) || /\bR\b/.test(text(formula.equation))) {
    notes.push("Use the molar gas constant R = 8.31 J mol^-1 K^-1.");
  }
  if (/gravitational constant|newton'?s law of gravitation|inverse-square/i.test(combined) || /\bG\b/.test(text(formula.equation))) {
    notes.push("Use G = 6.67 × 10^-11 N m^2 kg^-2.");
  }
  if (/elementary charge|electron charge|electronvolt|photoelectric/i.test(combined) || (/\be\b/.test(text(formula.equation)) && /charge/i.test(combined))) {
    notes.push("Use the elementary charge e = 1.60 × 10^-19 C.");
  }
  if (/avogadro/i.test(combined) || /N_A/.test(text(formula.equation))) {
    notes.push("Use Avogadro's constant N_A = 6.02 × 10^23 mol^-1.");
  }
  if (/permittivity of free space|epsilon|ε0/.test(combined) || /ε0/.test(text(formula.equation))) {
    notes.push("Use ε0 = 8.85 × 10^-12 F/m when the relation needs free-space permittivity.");
  }
  if (/permeability of free space|mu0|μ0/.test(combined) || /μ0/.test(text(formula.equation))) {
    notes.push("Use μ0 = 4π × 10^-7 H/m when the relation needs free-space permeability.");
  }
  if (/boltzmann/i.test(combined) || /\bk\b/.test(text(formula.equation))) {
    notes.push("Use Boltzmann's constant k = 1.38 × 10^-23 J K^-1 when the kinetic model needs it.");
  }

  return dedupeText(notes);
}

function enhancedFormulaConstantsText(code: string, formula: UnknownRecord): string[] {
  const equationText = text(formula.equation);
  const combined = `${equationText} ${text(formula.meaning)} ${text(formula.conditions)}`;
  const notes = formulaConstantsText(code, formula).filter((note) => {
    if (note.startsWith("Use the molar gas constant")) {
      return /molar gas constant|ideal gas|gas law/i.test(combined) || /\bnRT\b/i.test(equationText);
    }
    if (note.startsWith("Use Boltzmann's constant")) {
      return /boltzmann|average kinetic energy|kinetic theory|ideal gas|temperature/i.test(combined) && /\bk\b/.test(equationText);
    }
    return true;
  });

  if (/coulomb|electrostatic|point charge|radial charge|test charge/i.test(combined) && /\bk\b/.test(equationText)) {
    notes.push("Use Coulomb's constant k = 8.99 × 10^9 N m^2 C^-2 in vacuum.");
  }
  if (/hubble|expanding universe|cosmology|redshift/i.test(combined) && /H0/i.test(equationText)) {
    notes.push("Use H₀ in the form given by the question, often about 70 km s^-1 Mpc^-1.");
  }
  if (/nuclear radius|scattering|rutherford|nucleus/i.test(combined) && (/\bR0\b/i.test(equationText) || /\br0\b/i.test(equationText))) {
    notes.push("Use R₀ about 1.2 × 10^-15 m in the simple nuclear-size relation R = R₀A^(1/3).");
  }
  if (/wien|peak wavelength|stellar spectra/i.test(combined) && /\bb\b/.test(equationText)) {
    notes.push("Use Wien's constant b = 2.90 × 10^-3 m K.");
  }
  if (/stefan|luminosity|blackbody/i.test(combined) && /sigma|\u03c3/i.test(equationText)) {
    notes.push("Use σ = 5.67 × 10^-8 W m^-2 K^-4 in the Stefan-Boltzmann relation.");
  }
  if (/half-life|decay constant|activity/i.test(combined) && /lambda|\u03bb/i.test(equationText)) {
    notes.push("Use λ = ln 2 / t_(1/2) when converting between decay constant and half-life.");
  }

  return dedupeText(notes);
}

function looksLikeStandardEquationText(formulaText: string): boolean {
  const compact = singleLineText(formulaText);
  if (!compact) return false;
  if (/[=<>]/.test(compact)) {
    return !/\b(analysis|inventory|identify|identified|depends|belongs|occurs|consistent|before|after|stays|keeps|must|should|built)\b/i.test(compact);
  }
  return /\b(sin|cos|tan|log|ln)\b/i.test(compact) || /\b[a-zA-Z]\b\s*[\^/*+-]\s*\b[a-zA-Z0-9]/.test(compact);
}

function mergeFormulaCards(...groups: UnknownRecord[][]): UnknownRecord[] {
  const seen = new Set<string>();
  const merged: UnknownRecord[] = [];

  groups.flat().forEach((card) => {
    const key = singleLineText(text(card.standard_formula)).toLowerCase();
    if (!key || seen.has(key)) return;
    seen.add(key);
    merged.push(card);
  });

  return merged;
}

function supplementalFormulaCards(lesson: UnknownRecord, code: string): UnknownRecord[] {
  return supplementalEquationFallbacksForLesson(code).map((entry) => {
    const formulaRecord = {
      equation: entry.standardFormula,
      meaning: entry.meaning || "",
      conditions: entry.conditions || "",
    };
    const constantNotes = dedupeText([
      ...enhancedFormulaConstantsText(code, formulaRecord),
      ...(entry.constants ? [entry.constants] : []),
    ]);
    return {
      standard_formula: canonicalizeFormulaSymbolText(entry.standardFormula),
      analogy_equivalent: normalizeRenderedPhysicsText(formulaAnalogyEquivalent(lesson, code, formulaRecord)),
      constants: normalizeRenderedPhysicsText(constantNotes.join(" ")),
      meaning: normalizeRenderedPhysicsText(ensureSentence(entry.meaning || "")),
      units_text: normalizeRenderedPhysicsText(entry.unitsText || ""),
      conditions: normalizeRenderedPhysicsText(ensureSentence(trimmedFormulaCondition(entry.conditions || ""))),
    };
  });
}

function formulaAnalogyEquivalent(lesson: UnknownRecord, code: string, formula: UnknownRecord): string {
  const analogyMap = asRecord(asRecord(lesson.authoring_contract).analogy_map);
  const comparison = ensureSentence(text(analogyMap.comparison));
  const mapping = analogyMappingLines(lesson);
  const mappingLine = mapping[0] || "";
  const formalMeaning = ensureSentence(text(formula.meaning));
  const formalCondition = ensureSentence(trimmedFormulaCondition(text(formula.conditions)));
  const coreModule = coreModuleNumber(code);
  if (coreModule !== null) {
    const label = CORE_MODULE_ANALOGY_LABELS[coreModule] || "Lesson-model";
    const meaning = ensureSentence(analogyTextForCoreModule(code, text(formula.meaning))) || comparison;
    const condition = formulaConditionInstruction(analogyTextForCoreModule(code, text(formula.conditions)));
    const bridgeParts = [
      meaning
        ? `${label} rule: ${meaning}`
        : `${label} rule: Match the formal relation to the lesson story before you calculate.`,
    ];
    if (mappingLine) bridgeParts.push(mappingLine);
    if (condition) bridgeParts.push(condition);
    return bridgeParts.join(" ");
  }

  const advancedModule = advancedModuleNumber(code);
  if (advancedModule !== null) {
    const label = ADVANCED_MODULE_ANALOGY_LABELS[advancedModule] || "Lesson-model";
    const analogySentence = comparison || ensureSentence(firstAnalogySentence(lesson));
    const bridgeParts = [
      analogySentence
        ? `${label} bridge: ${analogySentence}`
        : `${label} bridge: Match the formal relation to the lesson model before you calculate.`,
    ];
    if (mappingLine) bridgeParts.push(mappingLine);
    if (formalMeaning) bridgeParts.push(`This relation tracks ${lowerFirst(formalMeaning)}.`);
    if (formalCondition) bridgeParts.push(formulaConditionInstruction(text(formula.conditions), "Use this relation"));
    return bridgeParts.join(" ");
  }

  return "Match the formal relation to the lesson model before you calculate.";
}

function authoredFormulaCards(lesson: UnknownRecord, code: string): UnknownRecord[] {
  const formulaCards: UnknownRecord[] = [];

  lessonFormulaRecords(lesson).forEach((formula) => {
    const standardFormula = standardFormulaText(formula);
    if (!standardFormula || !looksLikeStandardEquationText(standardFormula)) return;
    const constantNotes = enhancedFormulaConstantsText(code, formula);
    formulaCards.push({
      standard_formula: canonicalizeFormulaSymbolText(standardFormula),
      analogy_equivalent: normalizeRenderedPhysicsText(formulaAnalogyEquivalent(lesson, code, formula)),
      constants: normalizeRenderedPhysicsText(constantNotes.join(" ")),
      meaning: normalizeRenderedPhysicsText(ensureSentence(text(formula.meaning))),
      units_text: normalizeRenderedPhysicsText(formulaUnitsText(formula)),
      conditions: normalizeRenderedPhysicsText(ensureSentence(trimmedFormulaCondition(text(formula.conditions)))),
    });
  });

  return formulaCards;
}

function localM9FormulaFallbacks(code: string): Array<{ standardFormula: string; meaning?: string; conditions?: string; unitsText?: string; constants?: string }> {
  switch (code) {
    case "M9_L1":
      return [
        { standardFormula: "a steady current needs a complete circuit", meaning: "Charge carriers need one unbroken conducting path for sustained flow.", conditions: "Use when explaining why current stops or continues in a simple loop.", unitsText: "" },
        { standardFormula: "charge is conserved around the circuit", meaning: "Charge carriers circulate through the loop rather than being used up by a component.", conditions: "Use when separating charge flow from energy transfer.", unitsText: "C" },
      ];
    case "M9_L2":
      return [
        { standardFormula: "I = Q / t", meaning: "Current is charge flow rate.", conditions: "Use when the charge passing a point and the time taken are known.", unitsText: "A, C, s" },
        { standardFormula: "Q = It", meaning: "Charge passed depends on current and time.", conditions: "Use when the current is steady over the stated interval.", unitsText: "C" },
      ];
    case "M9_L3":
      return [
        { standardFormula: "V = E / Q", meaning: "Potential difference is energy transferred per unit charge.", conditions: "Use when the energy per coulomb is being compared.", unitsText: "V, J/C" },
        { standardFormula: "E = VQ", meaning: "Energy transferred depends on potential difference and charge moved.", conditions: "Use when voltage and charge are known.", unitsText: "J" },
      ];
    case "M9_L4":
      return [
        { standardFormula: "R is proportional to length / area", meaning: "For the same material, resistance rises with length and falls with cross-sectional area.", conditions: "Use when comparing wires of the same material.", unitsText: "" },
        { standardFormula: "greater length -> greater resistance", meaning: "A longer route gives charge carriers more opposition.", conditions: "Use when comparing wires of the same material and cross-sectional area.", unitsText: "" },
        { standardFormula: "greater cross-sectional area -> lower resistance", meaning: "A wider route gives charge carriers more room to move.", conditions: "Use when comparing wires of the same material and length.", unitsText: "" },
        { standardFormula: "resistance depends on material and geometry", meaning: "Resistance belongs to the route, not to the source.", conditions: "Use when comparing components or wires qualitatively.", unitsText: "" },
      ];
    case "M9_L5":
      return [
        { standardFormula: "V = IR", meaning: "Potential difference, current, and resistance are linked by Ohm's law for ohmic conductors.", conditions: "Use for ohmic components when conditions stay constant.", unitsText: "V, A, ohms" },
        { standardFormula: "I = V / R", meaning: "At fixed resistance, larger voltage gives larger current.", conditions: "Use for ohmic components.", unitsText: "A" },
        { standardFormula: "straight I-V graph through the origin -> current is proportional to voltage", meaning: "A straight origin-passing I-V graph is the ohmic clue.", conditions: "Use when interpreting I-V data or graph shape.", unitsText: "" },
      ];
    case "M9_L6":
      return [
        { standardFormula: "current is the same at every point in a series circuit", meaning: "One path means the same charge flow rate through every component.", conditions: "Use for a single-path circuit.", unitsText: "A" },
        { standardFormula: "voltage is the same across parallel branches", meaning: "Each parallel branch shares the same two junctions and so the same potential difference.", conditions: "Use for branches connected across the same supply.", unitsText: "V" },
        { standardFormula: "I_total = I1 + I2 + ...", meaning: "Source current equals the sum of the branch currents in a parallel circuit.", conditions: "Use at a junction where current splits or recombines.", unitsText: "A" },
        { standardFormula: "R_total = R1 + R2 + ...", meaning: "Series resistances add directly because there is one path through all components.", conditions: "Use for components in series.", unitsText: "ohms" },
        { standardFormula: "1 / R_total = 1 / R1 + 1 / R2 + ...", meaning: "Parallel branches reduce the overall opposition because they provide multiple current routes.", conditions: "Use for resistors connected in parallel.", unitsText: "ohms" },
        { standardFormula: "mixed circuits are reduced section by section", meaning: "Only the valid local series or parallel block should be combined at each stage.", conditions: "Use before calculating total current or branch values in a mixed network.", unitsText: "" },
      ];
    default:
      return [];
  }
}

function remappedLateCoreFormulaCode(code: string): string {
  const normalized = String(code || "").trim().replace(/-/g, "_").toUpperCase();
  return normalized;
}

function preferLocalCoreFormulaCards(code: string): boolean {
  const normalized = String(code || "").trim().replace(/-/g, "_").toUpperCase();
  if (normalized.startsWith("M9_") || normalized.startsWith("M10_") || normalized.startsWith("M11_") || normalized.startsWith("M12_")) return true;
  return remappedLateCoreFormulaCode(code) !== normalized;
}

function coreFormulaFallbackEntries(code: string): Array<{ targetCode: string; entry: { standardFormula: string; meaning?: string; conditions?: string; unitsText?: string; constants?: string } }> {
  if (code.startsWith("M9_")) {
    return localM9FormulaFallbacks(code).map((entry) => ({ targetCode: code, entry }));
  }

  const targetCode = remappedLateCoreFormulaCode(code);
  return coreFormulaFallbacksForLesson(targetCode).map((entry) => ({ targetCode, entry }));
}

function coreFormulaRows(lesson: UnknownRecord): UnknownRecord[] {
  const code = lessonCode(lesson);
  if (!isM1ToM14Lesson(code)) return [];
  const effectiveCode = remappedLateCoreFormulaCode(code);
  const fallbackEntries = coreFormulaFallbackEntries(code);

  const authoredCards = preferLocalCoreFormulaCards(code) ? [] : authoredFormulaCards(lesson, effectiveCode);
  const fallbackCards = fallbackEntries.map(({ targetCode, entry }) => {
    const formulaRecord = {
      equation: entry.standardFormula,
      meaning: entry.meaning || "",
      conditions: entry.conditions || "",
    };
    const constantNotes = dedupeText([
      ...enhancedFormulaConstantsText(targetCode, formulaRecord),
      ...(entry.constants ? [entry.constants] : []),
    ]);
    return {
      standard_formula: canonicalizeFormulaSymbolText(entry.standardFormula),
      analogy_equivalent: normalizeRenderedPhysicsText(formulaAnalogyEquivalent(lesson, targetCode, formulaRecord)),
      constants: normalizeRenderedPhysicsText(constantNotes.join(" ")),
      meaning: normalizeRenderedPhysicsText(ensureSentence(entry.meaning || "")),
      units_text: normalizeRenderedPhysicsText(entry.unitsText || ""),
      conditions: normalizeRenderedPhysicsText(ensureSentence(trimmedFormulaCondition(entry.conditions || ""))),
    };
  });

  return mergeFormulaCards(authoredCards, fallbackCards, supplementalFormulaCards(lesson, effectiveCode));
}

function formulaBridgeSection(lesson: UnknownRecord): UnknownRecord | null {
  const code = lessonCode(lesson);
  if (!isM1ToM14Lesson(code) && !isA1ToA11Lesson(code)) return null;

  const formulaCards = isM1ToM14Lesson(code)
    ? coreFormulaRows(lesson)
    : mergeFormulaCards(authoredFormulaCards(lesson, code), supplementalFormulaCards(lesson, code));

  if (!formulaCards.length) return null;

  const { rows, constantNote, sharedAnalogy } = formulaSectionRows(formulaCards);

  return {
    heading: "Standard formulas and analogy bridge",
    body: "Match each formal relation to the lesson model before you start the worked example. Keep the formula, its lesson meaning, and any fixed constants together so the symbols stay tied to the actual physics story.",
    formula_reference_rows: rows,
    formula_constants_note: constantNote,
    shared_formula_analogy: sharedAnalogy,
  };
}

function relationTeachingSection(lesson: UnknownRecord): UnknownRecord | null {
  const code = lessonCode(lesson);
  if (isM1ToM14Lesson(code) && preferLocalCoreFormulaCards(code)) {
    const formulaCard = coreFormulaRows(lesson)[0];
    if (!formulaCard) return null;

    const equation = canonicalizeFormulaSymbolText(text(formulaCard.standard_formula));
    const meaning = ensureSentence(text(formulaCard.meaning));
    const condition = ensureSentence(trimmedFormulaCondition(text(formulaCard.conditions)));
    const bodyParts = [
      equation ? `The compact lesson relation is ${equation}.` : "",
      meaning ? `It means ${lowerFirst(meaning)}` : "",
      condition ? formulaConditionInstruction(text(formulaCard.conditions), "Use this relation") : "",
      "Say this relation in words before you answer later quick checks or mastery questions.",
    ].filter(Boolean);

    return {
      heading: "Lesson relation",
      body: normalizeRenderedPhysicsText(bodyParts.join(" ")),
      analogy: normalizeRenderedPhysicsText(text(formulaCard.analogy_equivalent)),
      check_for_understanding: "What physical relationship does this lesson relation summarize?",
    };
  }

  const formula = lessonFormulaRecords(lesson).find((candidate) => {
    const standardFormula = standardFormulaText(candidate);
    return Boolean(standardFormula && looksLikeStandardEquationText(standardFormula));
  });
  if (!formula) return null;

  const equation = canonicalizeFormulaSymbolText(standardFormulaText(formula));
  const meaning = ensureSentence(text(formula.meaning));
  const condition = ensureSentence(trimmedFormulaCondition(text(formula.conditions)));
  const analogyBridge = isM1ToM14Lesson(code) || isA1ToA11Lesson(code)
    ? formulaAnalogyEquivalent(lesson, code, formula)
    : foundationFormulaAnalogyEquivalent(lesson, code, formula);

  const bodyParts = [
    equation ? `The compact lesson relation is ${equation}.` : "",
    meaning ? `It means ${lowerFirst(meaning)}` : "",
    condition ? formulaConditionInstruction(text(formula.conditions), "Use this relation") : "",
    "Say this relation in words before you answer later quick checks or mastery questions.",
  ].filter(Boolean);

  return {
    heading: "Lesson relation",
    body: normalizeRenderedPhysicsText(bodyParts.join(" ")),
    analogy: normalizeRenderedPhysicsText(analogyBridge),
    check_for_understanding: "What physical relationship does this lesson relation summarize?",
  };
}

function hasLessonRelationSection(sections: UnknownRecord[]): boolean {
  return sections.some((section) => /lesson relation/i.test(text(asRecord(section).heading)));
}

function authoredScaffoldSections(lesson: UnknownRecord, repairText: string, analogyText: string, workedExample: UnknownRecord): UnknownRecord[] {
  const code = lessonCode(lesson);
  const scaffoldSupport = asRecord(asRecord(lesson.authoring_contract).scaffold_support);
  if (Object.keys(scaffoldSupport).length === 0) return [];

  const analogyBridge = asRecord(scaffoldSupport.analogy_bridge);
  const extraSections = asList(scaffoldSupport.extra_sections)
    .map(asRecord)
    .filter((section) => text(section.heading) && text(section.body))
    .map((section) => ({
      heading: normalizeRenderedPhysicsText(text(section.heading)),
      body: normalizeRenderedPhysicsText(text(section.body)),
      check_for_understanding: normalizeRenderedPhysicsText(text(section.check_for_understanding)),
    }));
  const formulaBridge = formulaBridgeSection(lesson);

  return [
    { heading: "Fix these ideas", body: normalizeRenderedPhysicsText(repairText) },
    { heading: "Core idea", body: normalizeRenderedPhysicsText(text(scaffoldSupport.core_idea)) },
    {
      heading: "How to reason through it",
      body: normalizeRenderedPhysicsText(text(scaffoldSupport.reasoning)),
      check_for_understanding: normalizeRenderedPhysicsText(text(scaffoldSupport.check_for_understanding)),
    },
    { heading: "Common trap", body: normalizeRenderedPhysicsText(text(scaffoldSupport.common_trap)) },
    {
      heading: "Analogy",
      body: normalizeRenderedPhysicsText(text(analogyBridge.body)),
      analogy: normalizeRenderedPhysicsText(analogyText || "Use this analogy to compare the whole situation before you choose a formula or answer."),
      check_for_understanding: normalizeRenderedPhysicsText(text(analogyBridge.check_for_understanding)),
    },
    ...extraSections,
    ...(code.startsWith("M3_") ? m3SupplementalScaffoldSections(code) : []),
    ...(code.startsWith("M4_") ? m4SupplementalScaffoldSections(code) : []),
    ...(formulaBridge ? [formulaBridge] : []),
    ...scaffoldWorkedExampleSections(workedExample),
    ...(code.startsWith("M3_") ? m3SupplementalWorkedExampleSections(code) : []),
  ];
}

function scaffoldExtendedExtraSections(code: string): UnknownRecord[] {
  switch (code) {
    case "M2_L6":
      return [
        {
          heading: "Reading direction in degrees",
          body: "After you combine to get the net x and net y components, draw the rebuilt resultant from the origin to that net component point. The direction is measured counterclockwise from the +x axis to that arrow. In first-quadrant cases, use tan(theta) = y / x; in all cases, keep the signs of x and y visible so you place the angle in the correct quadrant.",
          check_for_understanding: "If a rebuilt vector has +x and +y components, where do you start measuring the direction angle, and what ratio tells you the angle size?",
        },
      ];
    default:
      return [];
  }
}

function attachScaffoldSectionVisuals(code: string, sections: UnknownRecord[]): UnknownRecord[] {
  if (!code.startsWith("M8_")) return sections;
  return sections.map((section) => {
    const sectionRecord = asRecord(section);
    const heading = text(sectionRecord.heading);
    const visual = m8ScaffoldSectionVisual(code, heading);
    return visual ? { ...sectionRecord, visual } : sectionRecord;
  });
}

