function scaffoldLessonNumber(code: string): number {
  const match = code.match(/_L(\d+)$/);
  return match ? Number(match[1]) : 1;
}

function scaffoldFirstSentence(value: string): string {
  const cleaned = normalizeRenderedPhysicsText(value).replace(/\s+/g, " ").trim();
  if (!cleaned) return "";
  const match = cleaned.match(/^(.+?[.!?])(?:\s|$)/);
  return (match ? match[1] : cleaned).trim();
}

function scaffoldDecapitalize(value: string): string {
  if (!value) return value;
  return value.charAt(0).toLowerCase() + value.slice(1);
}

function scaffoldRelevantSectionBody(sections: UnknownRecord[]): string {
  for (const section of sections) {
    const record = asRecord(section);
    const heading = text(record.heading).trim().toLowerCase();
    if (["fix these ideas", "analogy", "worked example", "technical words"].includes(heading)) continue;
    const body = scaffoldFirstSentence(text(record.body));
    if (body) return body;
  }
  return "";
}

function scaffoldRelevantMediaSentence(mediaCards: UnknownRecord[]): string {
  for (const card of mediaCards) {
    const record = asRecord(card);
    const caption = scaffoldFirstSentence(text(record.caption));
    if (caption) return caption;
    const title = scaffoldFirstSentence(text(record.title));
    if (title) return title;
  }
  return "";
}

function scaffoldObjectiveBullets(context: ScaffoldIntroContext): string[] {
  const focusBullets = dedupeText(context.teachingFocus).slice(0, 4);
  if (focusBullets.length > 0) {
    return focusBullets.map(scaffoldObjectiveFromText);
  }
  const mediaHighlights = dedupeText(
    context.mediaCards.flatMap((card) =>
      asList(asRecord(card).highlights).map((entry) => text(entry)).filter(Boolean),
    ),
  ).slice(0, 4);
  if (mediaHighlights.length > 0) {
    return mediaHighlights.map(scaffoldObjectiveFromText);
  }
  const sectionBodies = context.sections
    .map((section) => scaffoldFirstSentence(text(asRecord(section).body)))
    .filter(Boolean)
    .slice(0, 3);
  return sectionBodies.length > 0
    ? sectionBodies.map(scaffoldObjectiveFromText)
    : [
        `explain the main lesson idea in ${context.title}`,
        `use the key representation and language from this lesson correctly`,
        `connect this lesson to the wider module rather than treating it as an isolated fact`,
      ];
}

function scaffoldObjectiveFromText(value: string): string {
  const cleaned = normalizeRenderedPhysicsText(value).replace(/[.]+$/, "").trim();
  const lowered = scaffoldDecapitalize(cleaned);
  if (!lowered) return cleaned;
  if (/^(identify|distinguish|define|explain|compare|calculate|predict|apply|use|interpret|classify|suggest|evaluate|connect|resolve|analyze|analyse|read|choose|state|describe|justify|outline|estimate)\b/i.test(cleaned)) {
    return lowered;
  }
  if (/\b(is|are|means|depends|comes|keeps|requires|must|can|will|belongs|shows|tracks|changes|links|gives|describes|explains)\b/i.test(lowered)) {
    return `explain why ${lowered}`;
  }
  return `explain and apply ${lowered}`;
}

function scaffoldIntroTheme(context: ScaffoldIntroContext): ScaffoldIntroTheme {
  const relevantText = [
    context.title,
    ...context.teachingFocus,
    ...context.mediaCards.map((card) => text(asRecord(card).title)),
    ...context.mediaCards.map((card) => text(asRecord(card).caption)),
    ...context.sections.map((section) => text(asRecord(section).heading)),
    ...context.sections.map((section) => text(asRecord(section).body)),
  ]
    .join(" ")
    .toLowerCase();

  if (/(quark|baryon|meson|lepton|hadron|antiparticle|pair production|annihilation|exchange particle|conservation ledger|particle event)/.test(relevantText)) {
    return {
      area: "particle physics",
      history: "Modern particle physics grew out of scattering experiments, accelerator evidence, and conservation laws that forced scientists to classify particles and interactions more carefully than everyday language ever could.",
      starterPrereq: "There are no formal prerequisites beyond secure basic physics literacy and a willingness to track particles, charges, and event changes carefully.",
      continuingPrereq: "Learners should already be comfortable with the earlier particle-physics language in this module, because later lessons depend on classification, interaction clues, and conservation reasoning being held together accurately.",
      starterAudience: "This lesson is for learners beginning particle physics and needing a reliable way to classify matter, radiation, and interaction evidence from the start.",
      progressingAudience: "This lesson is for learners extending particle-physics reasoning into more rigorous classification, conservation, and event-analysis questions.",
      capstoneAudience: "This lesson is for learners consolidating particle physics and preparing to combine several earlier particle ideas in demanding IGCSE-style event questions.",
    };
  }
  if (/(energy level|photoelectric|de broglie|ionisation|excitation|line spectra|quantum|photon|discrete state|absorption line|emission line)/.test(relevantText)) {
    return {
      area: "quantum and atomic physics",
      history: "Quantum theory emerged when spectra, threshold effects, and atomic behaviour stopped fitting continuous classical models. Physicists had to accept discrete energy states and packet-like transfers to explain the evidence.",
      starterPrereq: "There are no formal prerequisites beyond secure school-level algebra, graph reading, and a willingness to compare models with experimental evidence carefully.",
      continuingPrereq: "Learners should already be comfortable with the earlier atomic and quantum ideas in this module, because later reasoning depends on discrete levels, thresholds, and evidence-based comparison staying visible together.",
      starterAudience: "This lesson is for learners beginning quantum and atomic physics and needing a clear entry point into discrete states, photons, and evidence-based models.",
      progressingAudience: "This lesson is for learners extending atomic and quantum reasoning into stronger explanations, threshold arguments, and calculation-supported interpretation.",
      capstoneAudience: "This lesson is for learners consolidating quantum and atomic physics and preparing to compare several strands of evidence within one coherent model.",
    };
  }
  if (/(wave|interference|diffraction|refraction|critical angle|total internal reflection|oscilloscope|stationary wave|standing wave|superposition|grating|spectrum line)/.test(relevantText)) {
    return {
      area: "wave physics",
      history: "Wave ideas were strengthened by sound, light, and pattern evidence showing that many apparently different phenomena could be explained through superposition, propagation, interference, and boundary behaviour.",
      starterPrereq: "There are no formal prerequisites beyond basic graph reading and secure measurement language. The lesson is designed to establish the key wave vocabulary before more demanding applications appear.",
      continuingPrereq: "Learners should already be secure with the earlier wave ideas in this module, because later work depends on keeping pattern, path, phase, and representation connected.",
      starterAudience: "This lesson is for learners beginning wave physics and needing a stable model before moving into interference, optics, and representation-heavy questions.",
      progressingAudience: "This lesson is for learners extending wave reasoning into more rigorous pattern explanation, comparison, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating wave physics and preparing to use several wave ideas together in more demanding explanations and problems.",
    };
  }
  if (/(magnetic|electromagnet|induction|generator|transformer|flux|field line|motor effect|side-kick|coil|solenoid|electromagnetic)/.test(relevantText)) {
    return {
      area: "magnetism and electromagnetism",
      history: "Magnetism became far more powerful once scientists linked permanent magnets, current-carrying conductors, induction, and electrical machines through the common language of fields and changing flux.",
      starterPrereq: "There are no formal prerequisites beyond secure basic algebra and a willingness to interpret direction, field patterns, and cause-and-effect carefully.",
      continuingPrereq: "Learners should already be comfortable with the earlier magnetism ideas in this module, because later lessons depend on field patterns, current direction, and changing flux being tracked consistently.",
      starterAudience: "This lesson is for learners beginning magnetism and electromagnetism and needing a secure field-based picture before motors, generators, or induction are analysed in depth.",
      progressingAudience: "This lesson is for learners extending magnetism and electromagnetism into more structured direction, force, and induction reasoning.",
      capstoneAudience: "This lesson is for learners consolidating magnetism and electromagnetism and preparing to link several earlier field ideas in multi-step questions.",
    };
  }
  if (/(circuit|current|voltage|potential difference|resistance|series|parallel|charge flow|power|ohm|divider|capacitor|rc|p\.d\.)/.test(relevantText)) {
    return {
      area: "electric circuits",
      history: "Electrical science matured when charge flow, potential difference, resistance, and component behaviour were tied together into circuit models that could explain measurements rather than just describe apparatus.",
      starterPrereq: "There are no formal prerequisites beyond basic algebra, unit handling, and careful comparison of simple physical quantities.",
      continuingPrereq: "Learners should already be secure with the earlier circuit ideas in this module, because later reasoning depends on current, p.d., resistance, and component roles being kept distinct and connected.",
      starterAudience: "This lesson is for learners beginning electric-circuit physics and needing a secure starting model before multi-component reasoning and quantitative work become heavier.",
      progressingAudience: "This lesson is for learners extending circuit reasoning into more rigorous explanation, prediction, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating electric-circuit physics and preparing to combine several earlier circuit ideas in challenging problems.",
    };
  }
  if (/(electric field|equipotential|coulomb|potential|field strength|uniform field|parallel plates|gravitational field|gravitational potential|orbit|satellite|planet|star|moon|sun|eclipse|solar system|luminosity|h-r|redshift|cosmology|astronomy|gravity)/.test(relevantText)) {
    return {
      area: "space, gravity, and field physics",
      history: "From planetary motion to modern astrophysics, progress in this part of physics came from combining observation with field models so that orbits, potentials, stars, and large-scale structure could be explained quantitatively rather than descriptively.",
      starterPrereq: "There are no formal prerequisites beyond secure algebra, graph reading, and a willingness to connect physical models with astronomical or field evidence.",
      continuingPrereq: "Learners should already be comfortable with the earlier ideas in this module, because later lessons depend on linking representation, model, and evidence across several related field or astronomy concepts.",
      starterAudience: "This lesson is for learners beginning the gravity, space, or field sequence and needing a secure model before orbit, stellar, or cosmological reasoning becomes more demanding.",
      progressingAudience: "This lesson is for learners extending gravity, field, or astronomy reasoning into stronger explanation, comparison, and quantitative interpretation.",
      capstoneAudience: "This lesson is for learners consolidating space, gravity, or field physics and preparing to coordinate several earlier ideas in more advanced IGCSE-style questions.",
    };
  }
  if (/(proton|neutron|nucleus|nuclide|isotope|radioactive|decay|half-life|binding energy|mass defect|atomic number|mass number|electron shell|nuclear)/.test(relevantText)) {
    return {
      area: "atomic and nuclear physics",
      history: "Atomic and nuclear physics developed when spectra, scattering, isotopes, radioactivity, and nuclear-energy evidence forced scientists to refine the internal model of the atom and the nucleus.",
      starterPrereq: "There are no formal prerequisites beyond secure algebra, notation reading, and careful attention to symbols, charges, and conservation-style bookkeeping.",
      continuingPrereq: "Learners should already be secure with the earlier atomic or nuclear ideas in this module, because later lessons depend on notation, structural meaning, and event interpretation staying consistent.",
      starterAudience: "This lesson is for learners beginning atomic or nuclear physics and needing a secure model before notation, decay, and energy-change questions become more demanding.",
      progressingAudience: "This lesson is for learners extending atomic or nuclear reasoning into more rigorous explanation, notation, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating atomic or nuclear physics and preparing to combine several earlier structural and quantitative ideas in one answer.",
    };
  }
  if (/(measurement|unit|prefix|significant figure|uncertainty|precision|accuracy|resolution|density)/.test(relevantText)) {
    return {
      area: "measurement and scientific reporting",
      history: "Physics became more reliable when measurements stopped being local habits and became shared, standardized reports with agreed units, sensible precision, and explicit attention to uncertainty.",
      starterPrereq: "There are no formal prerequisites beyond basic arithmetic and a willingness to compare sizes, units, and readings carefully.",
      continuingPrereq: "Learners should already be comfortable with the earlier measurement ideas in this module, because later lessons depend on precise language, justified digits, and trustworthy method choices.",
      starterAudience: "This lesson is for learners beginning scientific measurement and needing secure habits before practical work and data analysis become more demanding.",
      progressingAudience: "This lesson is for learners extending measurement and reporting skills into more rigorous practical reasoning and calculated answers.",
      capstoneAudience: "This lesson is for learners consolidating measurement and scientific reporting before moving into more demanding practical and data-based physics work.",
    };
  }
  if (/(temperature|thermal|heat|specific heat|latent|gas|pressure|volume|boyle|charles|particle model|internal energy|cooling|heating)/.test(relevantText)) {
    return {
      area: "thermal physics and particle behaviour",
      history: "Thermal physics grew when heating, cooling, gas behaviour, and particle models were linked so that temperature change could be explained through energy transfer and microscopic motion instead of surface description alone.",
      starterPrereq: "There are no formal prerequisites beyond basic algebra, unit handling, and a willingness to connect macroscopic changes with particle-level explanations.",
      continuingPrereq: "Learners should already be comfortable with the earlier thermal ideas in this module, because later lessons depend on keeping energy transfer, particle behaviour, and state change linked carefully.",
      starterAudience: "This lesson is for learners beginning thermal physics and needing a clear model before gas laws, specific heat, or state-change reasoning becomes heavier.",
      progressingAudience: "This lesson is for learners extending thermal reasoning into stronger explanation, comparison, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating thermal physics and preparing to combine several earlier heating, gas, and particle ideas in more demanding questions.",
    };
  }
  if (/(force|velocity|acceleration|displacement|distance|speed|motion|momentum|collision|projectile|equilibrium|torque|moment|stability|vector|component|stress|strain|young|kinematics)/.test(relevantText)) {
    return {
      area: "mechanics",
      history: "Mechanics became a predictive science when motion, force, momentum, and turning effects were described with clear mathematical models instead of everyday impressions of 'push' and 'movement'.",
      starterPrereq: "There are no formal prerequisites beyond basic algebra, graph reading, and secure use of measurement language.",
      continuingPrereq: "Learners should already be comfortable with the earlier mechanics ideas in this module, because later lessons depend on those force, motion, or vector models staying precise.",
      starterAudience: "This lesson is for learners beginning mechanics and needing a secure model before graph, vector, momentum, or equilibrium reasoning grows more demanding.",
      progressingAudience: "This lesson is for learners extending mechanics into more structured explanation, comparison, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating mechanics and preparing to use several earlier motion or force ideas together in harder IGCSE-style questions.",
    };
  }
  if (/(energy|power|efficiency|work|store|gpe|kinetic|internal store|transfer)/.test(relevantText)) {
    return {
      area: "energy and power physics",
      history: "Energy ideas became central when physicists and engineers needed a consistent way to track what machines, lifting systems, heating processes, and motion were really transferring or wasting.",
      starterPrereq: "There are no formal prerequisites beyond secure arithmetic, unit handling, and a willingness to track quantities through a clear before-and-after story.",
      continuingPrereq: "Learners should already be comfortable with the earlier energy ideas in this module, because later lessons depend on energy stores, transfer routes, and efficiency language staying precise.",
      starterAudience: "This lesson is for learners beginning energy and power physics and needing a clear bookkeeping model before multi-step machine or transfer questions appear.",
      progressingAudience: "This lesson is for learners extending energy reasoning into stronger explanation, comparison, and calculation.",
      capstoneAudience: "This lesson is for learners consolidating energy and power physics and preparing to combine several earlier transfer ideas in more demanding questions.",
    };
  }
  return {
    area: "physics reasoning",
    history: "Physics advances when observed patterns are turned into repeatable models, precise language, and justified calculations instead of isolated facts.",
    starterPrereq: "There are no formal prerequisites beyond secure basic algebra, graph reading, and willingness to reason carefully from evidence.",
    continuingPrereq: "Learners should already be comfortable with the earlier lessons in this module, because later work depends on reusing that language and structure accurately.",
    starterAudience: "This lesson is for learners beginning a new stretch of physics and needing a secure conceptual starting point.",
    progressingAudience: "This lesson is for learners extending earlier ideas into more structured explanation, comparison, and calculation.",
    capstoneAudience: "This lesson is for learners consolidating a run of physics ideas before harder multi-step questions.",
  };
}

function scaffoldGeneratedLessonIntroduction(context: ScaffoldIntroContext): ScaffoldIntroSection[] {
  const { code, title } = context;
  const lessonNumber = scaffoldLessonNumber(code);
  const theme = scaffoldIntroTheme(context);
  const summarySource = scaffoldRelevantSectionBody(context.sections) || scaffoldRelevantMediaSentence(context.mediaCards);
  const summary = summarySource || `${title} keeps the main lesson relationship visible before the learner moves into worked explanations and examples.`;
  const prerequisiteBody = lessonNumber === 1
    ? theme.starterPrereq
    : lessonNumber === 6
    ? `Learners should already be secure with the earlier lessons in this module, because this final lesson is strongest when several ${theme.area} ideas can be combined and compared fluently.`
    : theme.continuingPrereq;
  const audienceBody = lessonNumber === 1
    ? theme.starterAudience
    : lessonNumber === 6
    ? theme.capstoneAudience
    : theme.progressingAudience;

  return [
    {
      heading: "Historical background",
      body: theme.history,
    },
    {
      heading: "Lesson description",
      body: `${title} keeps the main lesson idea visible: ${summary}`,
    },
    {
      heading: "Learning objectives",
      body: "By the end of the lesson, the learner should be able to:",
      bullets: scaffoldObjectiveBullets(context),
    },
    {
      heading: "Prerequisites",
      body: prerequisiteBody,
    },
    {
      heading: "Who this lesson is for",
      body: audienceBody,
    },
  ];
}
export async function getLessonRunner(moduleId: string, lessonId: string, options: RunnerLoadOptions = {}): Promise<UnknownRecord> {
  const resources = await loadResources(moduleId, lessonId, options);
  const runnerLesson = asRecord(resources.runner.lesson);
  let state = readState(moduleId, lessonId);
  const title = lessonTitle(resources.lesson, runnerLesson);
  const lessonStatus = text(runnerLesson.lesson_status);
  const masteryMeta = asRecord(runnerLesson.mastery_check);
  const masteryThreshold = numberValue(masteryMeta.threshold, 0.8);
  const bestMasteryScore = numberValue(runnerLesson.best_score, 0);
  const confirmedLessonCompletion = bestMasteryScore >= masteryThreshold;
  const backendStage = text(runnerLesson.active_stage);
  const startStage = firstStageForLesson(resources.lesson);
  const serverCompletedStages = completedStageKeys(runnerLesson);
  const inferredServerStage = inferredStageFromServerProgress(resources.lesson, runnerLesson);
  const inferredStageIndex = runnerStageIndex(inferredServerStage || "");
  const backendStageIndex = runnerStageIndex(backendStage);
  const normalizedBackendStage = (
    backendStage === "done" &&
    !confirmedLessonCompletion &&
    availableStageKeys(resources.lesson, runnerLesson).includes("mastery_check")
  )
    ? "mastery_check"
    : backendStage;
  const normalizedBackendStageIndex = runnerStageIndex(normalizedBackendStage);
  // The backend owns the lesson state machine; client inference is only a fallback
  // when the stage is missing or malformed.
  const serverStage = normalizedBackendStageIndex >= 0
    ? normalizedBackendStage
    : inferredStageIndex >= 0
      ? inferredServerStage || startStage
      : startStage;
  const localDiagnosticReadyForScaffold = (
    serverStage === "diagnostic" &&
    Boolean(state.diagnostic?.acknowledged) &&
    (
      (state.diagnostic?.feedback?.length ?? 0) > 0 ||
      (state.diagnostic?.askedIds?.length ?? 0) > 0
    )
  );
  const shouldResetToStart = (
    lessonStatus === "not_started" &&
    serverCompletedStages.length === 0 &&
    !hasProgressBeforeMastery(runnerLesson, state)
  ) || (
    (serverStage === "mastery_check" || serverStage === "done") &&
    numberValue(masteryMeta.attempt_count, 0) < 1 &&
    !hasProgressBeforeMastery(runnerLesson, state)
  );

  if (shouldResetToStart) {
    clearState(moduleId, lessonId);
    state = {};
  }

  const syntheticConceptGate = !shouldResetToStart && shouldInjectConceptGate(resources.lesson, runnerLesson, serverStage, state);
  const localFloorStage = !shouldResetToStart ? localStageFloor(resources.lesson, runnerLesson, state) : null;
  const effectiveStage = shouldResetToStart
    ? startStage
    : syntheticConceptGate
      ? "concept_gate"
      : localFloorStage && runnerStageIndex(localFloorStage) > runnerStageIndex(serverStage)
        ? localFloorStage
      : localDiagnosticReadyForScaffold
        ? "scaffolded_teaching"
        : serverStage;
  const stage = (
    effectiveStage === "diagnostic" ||
    effectiveStage === "scaffolded_teaching" ||
    effectiveStage === "concept_gate" ||
    effectiveStage === "simulation" ||
    effectiveStage === "reflection" ||
    effectiveStage === "mastery_check" ||
    effectiveStage === "done"
  )
    ? effectiveStage
    : startStage;

  if (stage !== "diagnostic" && stage !== "scaffolded_teaching") delete state.diagnostic;
  if (stage !== "concept_gate") delete state.conceptGate;
  if (stage !== "reflection") delete state.reflection;
  if (stage !== "mastery_check" && stage !== "done") delete state.mastery;

  if (stage === "diagnostic") {
    state.diagnostic = {
      nonce: state.diagnostic?.nonce || freshAttemptSeed(),
      askedIds: state.diagnostic?.askedIds || [],
      answers: state.diagnostic?.answers || {},
      feedback: state.diagnostic?.feedback,
      recentFeedback: state.diagnostic?.recentFeedback,
      complete: state.diagnostic?.complete,
      acknowledged: state.diagnostic?.acknowledged,
    };
  }

  if (stage === "concept_gate") {
    state.conceptGate = {
      nonce: state.conceptGate?.nonce || freshAttemptSeed(),
      retryCount: state.conceptGate?.retryCount || 0,
      submitted: state.conceptGate?.submitted,
      passed: state.conceptGate?.passed,
      feedback: state.conceptGate?.feedback,
      microReteach: state.conceptGate?.microReteach,
    };
  }

  if (stage === "mastery_check" || stage === "done") {
    state.mastery = {
      nonce: state.mastery?.nonce || freshAttemptSeed(),
      submitted: state.mastery?.submitted,
      submittedAt: state.mastery?.submittedAt,
      feedback: state.mastery?.feedback,
      result: state.mastery?.result,
      reviewRefs: state.mastery?.reviewRefs,
      reviewRequested: state.mastery?.reviewRequested,
      forceNewAttempt: state.mastery?.forceNewAttempt,
    };
  }

  writeState(moduleId, lessonId, state);

  let activeStage = "diagnostic";
  let stagePayload: UnknownRecord = {};

  if (stage === "diagnostic") {
    activeStage = "diagnostic";
    const pool = diagnosticItems(resources.lesson);
    const diagnosticNonce = state.diagnostic?.nonce || 0;
    const orderedPool = diagnosticPoolForAttempt(moduleId, lessonId, resources.lesson, diagnosticNonce);
    const askedIds = state.diagnostic?.askedIds || [];
    const answers = state.diagnostic?.answers || {};
    const gradedFeedback = askedIds
      .map((id) => pool.find((entry) => text(asRecord(entry).id) === id))
      .filter(Boolean)
      .map((entry) => grade(asRecord(entry), answers[text(asRecord(entry).id)], title));
    const feedback = (state.diagnostic?.feedback?.length ?? 0) > 0
      ? state.diagnostic?.feedback || []
      : gradedFeedback;
    const correctCount = feedback.filter((entry) => entry.is_correct === true).length;
    const targetCount = diagnosticTarget(correctCount, askedIds.length, pool.length);
    const nextItem = orderedPool.find((entry) => !askedIds.includes(text(asRecord(entry).id))) || null;
    const isComplete = Boolean(state.diagnostic?.complete) || (!nextItem && feedback.length > 0);
    if (isComplete && feedback.length > 0) {
      stagePayload = {
        instructions: "Here is the answer-by-answer feedback for this opening check.",
        question_count: feedback.length,
        questions: [],
        submitted: true,
        feedback,
      };
    } else {
      stagePayload = {
        instructions: askedIds.length < 2 ? "Question " + String(askedIds.length + 1) + " of at least 2." : "Question " + String(askedIds.length + 1) + " of " + String(targetCount) + ". Strong answers may unlock one more question.",
        question_count: targetCount,
        answered_count: askedIds.length,
        questions: nextItem ? [question(asRecord(nextItem), "diagnostic:" + String(diagnosticNonce) + ":" + String(askedIds.length))] : [],
        recent_feedback: state.diagnostic?.recentFeedback,
        action_label: "Check my answer",
      };
    }
  }

  else if (stage === "scaffolded_teaching") {
    activeStage = "scaffold";
    stagePayload = scaffoldPayload(title, resources.lesson, state.diagnostic?.feedback || []);
  }
  else if (stage === "concept_gate") {
    activeStage = "concept_gate";
    const retryCount = state.conceptGate?.retryCount || 0;
    const conceptNonce = state.conceptGate?.nonce || 0;
    const conceptSeed = "concept:" + String(conceptNonce) + ":" + String(retryCount);
    const gateItem = conceptGateItemForAttempt(moduleId, lessonId, resources.lesson, conceptNonce, retryCount);
    stagePayload = state.conceptGate?.submitted
      ? {
          instructions: "Use the feedback below to tighten the key idea before moving on.",
          retry_count: retryCount,
          max_retries: CONCEPT_GATE_MAX_RETRIES,
          questions: gateItem ? [question(asRecord(gateItem), conceptSeed)] : [],
          submitted: true,
          passed: state.conceptGate.passed,
          feedback: state.conceptGate.feedback,
          micro_reteach: asRecord(state.conceptGate).microReteach,
        }
      : {
          instructions: "Answer this quick check before you move on.",
          retry_count: retryCount,
          max_retries: CONCEPT_GATE_MAX_RETRIES,
          questions: gateItem ? [question(asRecord(gateItem), conceptSeed)] : [],
        };
  }
  else if (stage === "simulation") {
    activeStage = "simulation";
    const inquiry = asList(asRecord(phases(resources.lesson).simulation_inquiry).inquiry_prompts).map(asRecord);
    const generatedLab = asRecord(asRecord(phases(resources.lesson).simulation_inquiry).generated_lab);
    const simulationCode = lessonCode(resources.lesson);
    stagePayload = {
      title: simulationStageTitle(simulationCode),
      instructions: simulationStageInstructions(simulationCode, inquiry),
      embed_url: text(generatedLab.url),
      task_prompt: simulationStageTaskPrompt(simulationCode, inquiry),
      explore_steps: simulationStageExploreSteps(simulationCode),
      watch_for: simulationStageWatchFor(simulationCode),
      try_first: simulationStageTryFirst(simulationCode),
      takeaway: simulationStageTakeaway(simulationCode),
      completion_text: "I have finished exploring this activity",
    };
  }
  else if (stage === "reflection") {
    activeStage = "reflection";
    const prompts = [
      ...asList(asRecord(phases(resources.lesson).concept_reconstruction).prompts).map((entry) => text(entry)),
      ...authoredReflectionPrompts(resources.lesson),
    ].filter(Boolean);
    const inquiry = asList(asRecord(phases(resources.lesson).simulation_inquiry).inquiry_prompts).map(asRecord);
    stagePayload = {
      title: "Explain the idea back",
      prompt: prompts[0] || "Explain the key idea from this lesson in your own words.",
      guidance: inquiry.map((entry) => text(entry.hint) || text(entry.prompt)).filter(Boolean).slice(0, 3),
      visual_check: reflectionVisualCheck(resources.lesson),
      submitted: state.reflection?.submitted,
      learner_response: state.reflection?.learnerResponse,
    };
  }
  else {
    activeStage = "mastery";
    const masteryState = state.mastery || { nonce: 0 };
    const threshold = numberValue(masteryMeta.threshold, 0.8);
    const thresholdPercent = Math.round(threshold * 100);
    const bestScorePercent = Math.round(numberValue(runnerLesson.best_score, 0) * 100);
    const latestScore = typeof masteryMeta.latest_score === "number"
      ? numberValue(masteryMeta.latest_score, 0)
      : typeof runnerLesson.latest_score === "number"
        ? numberValue(runnerLesson.latest_score, 0)
        : null;
    const persistedResult = typeof latestScore === "number"
      ? { percent: Math.round(latestScore * 100), passed: latestScore >= threshold }
      : undefined;
    const hasPersistedResult = numberValue(masteryMeta.attempt_count, 0) >= 1 && Boolean(persistedResult) && masteryState.forceNewAttempt !== true;
    const localSubmissionIsFresh = Boolean(
      masteryState.submitted &&
      typeof masteryState.submittedAt === "number" &&
      (Date.now() - masteryState.submittedAt) <= LOCAL_MASTERY_RESULT_TTL_MS
    );
    const localFeedbackCount = asList(masteryState.feedback).length;
    const localResult = asRecord(masteryState.result);
    const localResultPercent = typeof localResult.percent === "number"
      ? numberValue(localResult.percent, 0)
      : null;
    const localResultPassed = typeof localResultPercent === "number"
      ? localResultPercent >= thresholdPercent
      : typeof localResult.passed === "boolean"
        ? Boolean(localResult.passed)
        : null;
    const localSubmittedResult = localSubmissionIsFresh && localFeedbackCount > 0 && typeof localResultPercent === "number"
      ? { percent: localResultPercent, passed: Boolean(localResultPassed) }
      : undefined;
    const confirmedMasteryResult = stage === "done" && bestScorePercent >= thresholdPercent
      ? { percent: bestScorePercent, passed: true }
      : undefined;
    const resolvedMasteryResult = localSubmittedResult || persistedResult || confirmedMasteryResult;
    const showSubmittedMastery = Boolean(resolvedMasteryResult) && (
      Boolean(localSubmittedResult) ||
      hasPersistedResult ||
      Boolean(confirmedMasteryResult)
    );
    const pool = masteryItems(resources.lesson);
    const strengthScore = masteryStrengthScore(runnerLesson, state);
    const count = masteryQuestionCount(masteryMeta, pool.length, strengthScore);
    const selectedPool = masteryPoolForAttempt(moduleId, lessonId, resources.lesson, masteryState.nonce || 0);
    const selected = selectedPool.slice(0, count);
    if (
      !hasPersistedResult &&
      !confirmedMasteryResult &&
      masteryState.submitted &&
      !localSubmittedResult
    ) {
      state.mastery = {
        nonce: masteryState.nonce || freshAttemptSeed(),
        displayedItems: asList(masteryState.displayedItems).map(asRecord),
        forceNewAttempt: masteryState.forceNewAttempt,
      };
    }
    if (!showSubmittedMastery) {
      writeState(moduleId, lessonId, {
        ...state,
        mastery: {
          ...(state.mastery || {}),
          nonce: masteryState.nonce || 0,
          displayedItems: selected.map((item) => asRecord(item)),
        },
      });
    }
    stagePayload = showSubmittedMastery
      ? {
          instructions: confirmedMasteryResult ? "You have already shown mastery for this lesson." : "This is your latest mastery result.",
          questions: [],
          submitted: true,
          feedback: masteryState.feedback || [],
          result: resolvedMasteryResult,
          review_refs: masteryState.reviewRefs || reviewRefs(resources.lesson, asList(masteryMeta.recommended_review_refs)),
          review_requested: Boolean(asRecord(masteryState).reviewRequested),
          min_questions: numberValue(masteryMeta.min_questions, 5),
          max_questions: numberValue(masteryMeta.max_questions, 10),
          passing_percent: thresholdPercent,
        }
      : {
          instructions: "Use what you learned in " + title + " to answer " + String(selected.length) + " final questions carefully.",
          question_count: selected.length,
          questions: selected.map((item, index) => question(asRecord(item), `mastery:${masteryState.nonce || 0}:${index}`)),
          min_questions: numberValue(masteryMeta.min_questions, 5),
          max_questions: numberValue(masteryMeta.max_questions, 10),
          passing_percent: Math.round(numberValue(masteryMeta.threshold, 0.8) * 100),
        };
  }

  const moduleMeta = asRecord(resources.runner.module);
  const finalMasteryMeta = asRecord(runnerLesson.mastery_check);
  const latestMasteryPercent = typeof finalMasteryMeta.latest_score === "number"
    ? Math.round(numberValue(finalMasteryMeta.latest_score, 0) * 100)
    : typeof runnerLesson.latest_score === "number"
      ? Math.round(numberValue(runnerLesson.latest_score, 0) * 100)
      : null;

  return {
    module_id: normalizeModuleId(text(moduleMeta.module_id) || moduleId),
    lesson_id: normalizeLessonIdForModule(moduleId, text(runnerLesson.lesson_id) || lessonId),
    lesson_title: title,
    lesson_status: confirmedLessonCompletion
      ? "completed"
      : text(runnerLesson.lesson_status) === "not_started"
        ? "not_started"
        : "in_progress",
    active_stage: activeStage,
    stage_payload: stagePayload,
    progress_summary: {
      attempts: numberValue(finalMasteryMeta.attempt_count),
      latest_mastery_percent: latestMasteryPercent,
      best_mastery_percent: Math.round(numberValue(runnerLesson.best_score) * 100),
      module_mastery_percent: Math.round(numberValue(moduleMeta.module_mastery) * 100),
      concept_gate_passed: asList(runnerLesson.stages).map(asRecord).some((entry) => text(entry.key) === "concept_gate" && entry.completed === true),
    },
  };
}

export async function postProgressEvent(moduleId: string, request: RunnerRequest, options: RunnerLoadOptions = {}): Promise<void> {
  const lessonId = normalizeLessonIdForModule(moduleId, request.lesson_id);
  const payload = request.payload || {};

  if (request.event_type === "diagnostic_submitted") {
    const resources = await loadResources(moduleId, lessonId, options);
    const title = lessonTitle(resources.lesson, asRecord(resources.runner.lesson));
    const pool = diagnosticItems(resources.lesson);
    const answers = asRecord(payload.answers);
    const firstEntry = Object.entries(answers)[0];
    if (!firstEntry) throw new Error("Choose an answer before continuing.");
    const [questionId, answerValue] = firstEntry;
    const item = pool.find((entry) => text(asRecord(entry).id) === questionId);
    if (!item) throw new Error("This question is not available right now.");

    const current = readState(moduleId, lessonId);
    const diagnosticNonce = current.diagnostic?.nonce || freshAttemptSeed();
    const askedIds = current.diagnostic?.askedIds || [];
    const nextAskedIds = askedIds.includes(questionId) ? askedIds : [...askedIds, questionId];
    const nextAnswers = { ...(current.diagnostic?.answers || {}), [questionId]: text(answerValue) };
    const graded = nextAskedIds
      .map((id) => pool.find((entry) => text(asRecord(entry).id) === id))
      .filter(Boolean)
      .map((entry) => grade(asRecord(entry), nextAnswers[text(asRecord(entry).id)], title));
    const currentFeedback = grade(asRecord(item), text(answerValue), title);
    const correctCount = graded.filter((entry) => entry.is_correct === true).length;
    const target = diagnosticTarget(correctCount, graded.length, pool.length);
    const complete = graded.length >= target || nextAskedIds.length >= pool.length;
    if (complete) writeDiagnosticAttemptHistory(moduleId, lessonId, resources.lesson, nextAskedIds);
    writeState(moduleId, lessonId, {
      ...current,
      diagnostic: { nonce: diagnosticNonce, askedIds: nextAskedIds, answers: nextAnswers, recentFeedback: currentFeedback, complete, feedback: complete ? graded : undefined },
      conceptGate: current.conceptGate,
      reflection: current.reflection,
      mastery: current.mastery,
    });
    return;



  }

  if (request.event_type === "diagnostic_feedback_acknowledged") {
    const state = readState(moduleId, lessonId);
    const resources = await loadResources(moduleId, lessonId, options);
    const title = lessonTitle(resources.lesson, asRecord(resources.runner.lesson));
    const diagnosticPool = diagnosticItems(resources.lesson);
    const diagnosticAnswers = state.diagnostic?.answers || {};
    const feedback = (state.diagnostic?.feedback?.length ?? 0) > 0
      ? state.diagnostic?.feedback || []
      : (state.diagnostic?.askedIds || [])
        .map((id) => diagnosticPool.find((entry) => text(asRecord(entry).id) === id))
        .filter(Boolean)
        .map((entry) => grade(asRecord(entry), diagnosticAnswers[text(asRecord(entry).id)], title));
    const correctCount = feedback.filter((entry) => entry.is_correct === true).length;
    const misconceptionTags = feedback
      .filter((entry) => entry.is_correct !== true)
      .map((entry) => text(entry.misconception_tag))
      .filter(Boolean);
    await postEvent(moduleId, lessonId, {
      event_type: "diagnostic",
      score: feedback.length > 0 ? correctCount / feedback.length : 0,
      misconception_tags: misconceptionTags,
      details: { source: "student_runner_diagnostic", asked_count: feedback.length, correct_count: correctCount },
    });
    writeState(moduleId, lessonId, {
      profile: {
        ...(state.profile || {}),
        diagnosticScore: feedback.length > 0 ? correctCount / feedback.length : 0,
        diagnosticReady: true,
      },
      diagnostic: {
        nonce: state.diagnostic?.nonce || freshAttemptSeed(),
        askedIds: state.diagnostic?.askedIds || [],
        answers: diagnosticAnswers,
        feedback,
        recentFeedback: state.diagnostic?.recentFeedback,
        complete: true,
        acknowledged: true,
      },
      conceptGate: state.conceptGate,
      reflection: state.reflection,
      mastery: state.mastery,
    });
    return;
  }

  if (request.event_type === "scaffold_continue") {
    const state = readState(moduleId, lessonId);
    await postEvent(moduleId, lessonId, {
      event_type: "reflection",
      score: 1,
      details: { source: "student_runner_scaffolded_teaching_viewed" },
    });
    writeState(moduleId, lessonId, {
      ...state,
      profile: {
        ...(state.profile || {}),
        scaffoldCompleted: true,
      },
      conceptGate: state.conceptGate || {
        nonce: freshAttemptSeed(),
        retryCount: 0,
      },
    });
    return;
  }

  if (request.event_type === "concept_gate_retry_requested") {
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      ...state,
      conceptGate: { nonce: state.conceptGate?.nonce || freshAttemptSeed(), retryCount: Math.min((state.conceptGate?.retryCount || 0) + 1, CONCEPT_GATE_MAX_RETRIES) },
    });
    return;
  }

  if (request.event_type === "concept_gate_submitted" && payload.acknowledged === true) {
    await postEvent(moduleId, lessonId, {
      event_type: "reflection",
      score: 1,
      details: { source: "student_runner_concept_gate" },
    });
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      profile: {
        ...(state.profile || {}),
        conceptGateReady: true,
      },
      diagnostic: state.diagnostic,
      reflection: state.reflection,
      mastery: state.mastery,
    });
    return;
  }

  if (request.event_type === "concept_gate_submitted") {
    const resources = await loadResources(moduleId, lessonId, options);
    const title = lessonTitle(resources.lesson, asRecord(resources.runner.lesson));
    const state = readState(moduleId, lessonId);
    const retryCount = state.conceptGate?.retryCount || 0;
    const conceptNonce = state.conceptGate?.nonce || freshAttemptSeed();
    const conceptPool = conceptGatePoolForAttempt(moduleId, lessonId, resources.lesson, conceptNonce);
    let item = conceptGateItemForAttempt(moduleId, lessonId, resources.lesson, conceptNonce, retryCount);
    const submittedAnswers = asRecord(payload.answers);
    const submittedQuestionIds = asList(payload.question_ids).map((entry) => text(entry)).filter(Boolean);
    const answeredQuestionId = submittedQuestionIds.find((id) => text(submittedAnswers[id]).trim())
      || Object.keys(submittedAnswers).find((id) => text(submittedAnswers[id]).trim())
      || submittedQuestionIds[0]
      || Object.keys(submittedAnswers)[0]
      || "";

    if (answeredQuestionId && (!item || text(asRecord(item).id) !== answeredQuestionId)) {
      const matchedItem = conceptPool.find((entry) => text(asRecord(entry).id) === answeredQuestionId);
      if (matchedItem) {
        item = asRecord(matchedItem);
      }
    }

    const answerValue = text(submittedAnswers[text(asRecord(item).id)] || submittedAnswers[answeredQuestionId]).trim();
    if (!item || !answerValue) throw new Error("Choose an answer before continuing.");
    const graded = grade(asRecord(item), answerValue, title);
    const capsules = asList(asRecord(phases(resources.lesson).concept_reconstruction).capsules).map(asRecord);
    writeConceptGateAttemptHistory(moduleId, lessonId, resources.lesson, [text(asRecord(item).id)]);
    const capsule = capsules.find((entry) => asList(entry.checks).map(asRecord).some((check) => text(check.id) === text(asRecord(item).id)));
    writeState(moduleId, lessonId, {
      ...state,
      conceptGate: {
        nonce: conceptNonce,
        retryCount,
        submitted: true,
        passed: graded.is_correct === true,
        feedback: [{ question_id: text(graded.question_id), is_correct: graded.is_correct, explanation: graded.is_correct === true ? "That is right. You have shown the key idea clearly." : `${text(graded.explanation)} Correct answer: ${text(graded.correct_answer)}.` }],
        microReteach: graded.is_correct === true ? undefined : {
          title: retryCount >= CONCEPT_GATE_MAX_RETRIES ? "Quick refresher" : "Remember this",
          body: normalizeRenderedPhysicsText(text(capsule?.prompt) || text(graded.teaching_focus)),
        },
      },
    });
    return;
  }

  if (request.event_type === "simulation_completed") {
    await postEvent(moduleId, lessonId, {
      event_type: "simulation",
      score: 1,
      details: { source: "student_runner_simulation" },
    });
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      ...state,
      profile: {
        ...(state.profile || {}),
        simulationReady: true,
      },
    });
    return;
  }

  if (request.event_type === "reflection_submitted" && payload.acknowledged === true) {
    const state = readState(moduleId, lessonId);
    await postEvent(moduleId, lessonId, {
      event_type: "reflection",
      score: 1,
      details: { source: "student_runner_concept_reconstruction", response_text: state.reflection?.learnerResponse || "" },
    });
    writeState(moduleId, lessonId, {
      profile: {
        ...(state.profile || {}),
        reflectionReady: true,
      },
      diagnostic: state.diagnostic,
      conceptGate: state.conceptGate,
      mastery: state.mastery,
    });
    return;
  }

  if (request.event_type === "reflection_submitted") {
    const responseText = text(payload.response_text).trim();
    if (!responseText) throw new Error("Write your explanation before continuing.");
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      ...state,
      reflection: { submitted: true, learnerResponse: responseText },
    });
    return;
  }

  if (request.event_type === "mastery_retest_requested") {
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      ...state,
      mastery: {
        nonce: (state.mastery?.nonce || freshAttemptSeed()) + 1,
        forceNewAttempt: true,
        displayedItems: [],
      },
    });
    return;
  }

  if (request.event_type === "mastery_review_requested") {
    const state = readState(moduleId, lessonId);
    writeState(moduleId, lessonId, {
      ...state,
      mastery: { ...(state.mastery || { nonce: freshAttemptSeed() }), reviewRequested: true },
    });
    return;
  }

  if (request.event_type === "mastery_submitted") {
    const resources = await loadResources(moduleId, lessonId, options);
    const runnerLesson = asRecord(resources.runner.lesson);
    const title = lessonTitle(resources.lesson, runnerLesson);
    const masteryMeta = asRecord(runnerLesson.mastery_check);
    const state = readState(moduleId, lessonId);
    const pool = masteryItems(resources.lesson);
    const submittedIds = asList(payload.question_ids).map((entry) => text(entry)).filter(Boolean);
    const displayedItems = asList(state.mastery?.displayedItems).map(asRecord).filter((item) => text(item.id));
    const displayedById = new Map(displayedItems.map((item) => [text(item.id), item]));
    const displayedSelected = submittedIds.length && submittedIds.every((id) => displayedById.has(id))
      ? submittedIds.map((id) => displayedById.get(id)).filter(Boolean)
      : [];
    const selected = displayedSelected.length === submittedIds.length && submittedIds.length > 0
      ? displayedSelected
      : submittedIds.length
        ? submittedIds.map((id) => pool.find((item) => text(asRecord(item).id) === id)).filter(Boolean)
        : masteryPoolForAttempt(moduleId, lessonId, resources.lesson, state.mastery?.nonce || 0).slice(0, masteryQuestionCount(masteryMeta, pool.length, masteryStrengthScore(runnerLesson, state)));
    if (submittedIds.length && selected.length !== submittedIds.length) throw new Error("This mastery check is out of date. Start a fresh attempt and try again.");
    if (selected.length === 0) throw new Error("The mastery check is not available right now.");
    const answers = asRecord(payload.answers);
    const feedback = selected.map((item) => {
      const graded = grade(asRecord(item), answers[text(asRecord(item).id)], title);
      return {
        question_id: text(graded.question_id),
        prompt: text(graded.prompt),
        is_correct: graded.is_correct,
        explanation: graded.is_correct === true ? text(graded.explanation) || "Correct." : `${text(graded.explanation)} Correct answer: ${text(graded.correct_answer)}.`,
      };
    });
    const correctCount = feedback.filter((entry) => entry.is_correct === true).length;
    const score = selected.length > 0 ? correctCount / selected.length : 0;
    const result = { percent: Math.round(score * 100), passed: score >= numberValue(masteryMeta.threshold, 0.8) };
    writeMasteryAttemptHistory(moduleId, lessonId, resources.lesson, selected.map((item) => text(asRecord(item).id)).filter(Boolean));
    writeState(moduleId, lessonId, {
      ...state,
      mastery: {
        nonce: state.mastery?.nonce || 0,
        submitted: true,
        submittedAt: Date.now(),
        feedback,
        result,
        reviewRefs: reviewRefs(resources.lesson, asList(masteryMeta.recommended_review_refs)),
        forceNewAttempt: false,
      },
    });
    await postEvent(moduleId, lessonId, {
      event_type: "transfer",
      score,
      details: { source: "student_runner_mastery_check", correct_count: correctCount },
    });
    return;
  }

  throw new Error(`Unsupported lesson runner event: ${request.event_type}`);
}


export async function restartModuleProgress(moduleId: string): Promise<void> {
  const normalizedModuleId = normalizeModuleId(moduleId);
  await apipPost<{ ok: boolean }, JsonObject>(
    "/student/modules/" + encodeURIComponent(normalizedModuleId) + "/restart",
    {}
  );
  clearModuleState(normalizedModuleId);
  clearModuleAttemptHistory(normalizedModuleId);
}

export async function restartLessonProgress(moduleId: string, lessonId: string): Promise<void> {
  const normalizedModuleId = normalizeModuleId(moduleId);
  const normalized = normalizeLessonIdForModule(normalizedModuleId, lessonId);
  await apipPost<{ ok: boolean }, JsonObject>(
    "/student/modules/" + encodeURIComponent(normalizedModuleId) + "/lessons/" + encodeURIComponent(normalized) + "/restart",
    {}
  );
  clearState(normalizedModuleId, normalized);
  clearAttemptHistory(normalizedModuleId, normalized);
}

